SELECT /* CASE nested-count */ ((COUNT(1))) > 0 FROM post_reads;
SELECT /* CASE nonnull-guard */ COUNT(slug)>0 FROM nullable_slugs WHERE slug IS NOT NULL;
SELECT 0 < (SELECT /* CASE reversed-count */ COUNT(*) FROM post_reads);
SELECT /* CASE negative-count-value */ COUNT(*)>0 AS has_rows, COUNT(*) AS n FROM post_reads;
SELECT /* CASE negative-count-bind */ COUNT($1)>0 FROM post_reads;
SELECT /* CASE negative-count-null */ COUNT(NULL)>0 FROM post_reads;
SELECT /* CASE negative-count-wildcard */ (SELECT * FROM (SELECT COUNT(*) AS n FROM post_reads) c)>0;
SELECT /* CASE negative-count-derived */ COUNT(c.n)>0 FROM (SELECT COUNT(*) AS n FROM post_reads) c;
SELECT /* CASE negative-max-no-comparison */ p.parent_id FROM posts p GROUP BY p.parent_id HAVING NOT EXISTS(SELECT 1 FROM posts old WHERE old.parent_id=p.parent_id) OR p.parent_id IS NULL;
SELECT /* CASE negative-max-multiple-from */ p.parent_id, MAX(p.created_at) FROM posts p, archived_posts a GROUP BY p.parent_id HAVING NOT EXISTS(SELECT 1 FROM posts old WHERE old.parent_id=p.parent_id) OR MAX(p.created_at)<'2025-01-01';
SELECT /* CASE negative-max-where-value */ p.parent_id, MAX(p.created_at) FROM posts p WHERE p.parent_id IS NOT NULL GROUP BY p.parent_id HAVING NOT EXISTS(SELECT 1 FROM posts old WHERE old.parent_id=p.parent_id) OR MAX(p.created_at)<'2025-01-01';
SELECT /* CASE negative-max-projected */ p.parent_id, MAX(p.created_at) FROM posts p GROUP BY p.parent_id HAVING NOT EXISTS(SELECT 1 FROM posts old WHERE old.parent_id=p.parent_id) OR MAX(p.created_at)<'2025-01-01';
SELECT /* CASE negative-max-scalar */ MAX(p.created_at) FROM posts p HAVING NOT EXISTS(SELECT 1 FROM posts old) OR MAX(p.created_at)<'2025-01-01';
SELECT /* CASE negative-max-inner-with */ p.parent_id FROM posts p GROUP BY p.parent_id HAVING NOT EXISTS(WITH counted AS (SELECT COUNT(*) AS n FROM posts old WHERE old.parent_id=p.parent_id) SELECT n FROM counted) OR MAX(p.created_at)<'2025-01-01';
SELECT /* CASE negative-max-inner-aggregate */ p.parent_id FROM posts p GROUP BY p.parent_id HAVING NOT EXISTS(SELECT COUNT(*) FROM posts old WHERE old.parent_id=p.parent_id) OR MAX(p.created_at)<'2025-01-01';
SELECT /* CASE negative-max-inner-having */ p.parent_id FROM posts p GROUP BY p.parent_id HAVING NOT EXISTS(SELECT 1 FROM posts old WHERE old.parent_id=p.parent_id HAVING COUNT(*)=0) OR MAX(p.created_at)<'2025-01-01';
SELECT /* CASE negative-max-inner-no-from */ p.parent_id FROM posts p GROUP BY p.parent_id HAVING NOT EXISTS(SELECT 1) OR MAX(p.created_at)<'2025-01-01';
SELECT /* CASE negative-max-other-table */ p.parent_id FROM posts p GROUP BY p.parent_id HAVING NOT EXISTS(SELECT 1 FROM archived_posts) OR MAX(p.created_at)<'2025-01-01';
SELECT /* CASE negative-derived-union */ p.id FROM posts p JOIN (SELECT id FROM posts UNION SELECT id FROM archived_posts) d ON d.id=p.id;
SELECT /* CASE negative-derived-wildcard */ p.id,d.deleted_at FROM posts p JOIN (SELECT DISTINCT * FROM live_topics) d ON d.topic_id=p.id;
SELECT /* CASE negative-derived-offset */ p.id FROM posts p JOIN (SELECT DISTINCT post_id FROM post_reads ORDER BY post_id OFFSET 1) d ON d.post_id=p.id;
SELECT /* CASE negative-derived-output */ d.* FROM posts p JOIN (SELECT DISTINCT post_id FROM post_reads) d ON d.post_id=p.id;
SELECT p.id FROM posts p WHERE p.id = ANY(SELECT /* CASE any-distinct-filter */ DISTINCT post_id FROM post_reads);
SELECT /* CASE negative-in-union */ p.id FROM posts p WHERE p.id IN(SELECT post_id FROM post_reads UNION SELECT id FROM archived_posts);
SELECT /* CASE negative-fanout-count-value */ COUNT(*) FROM posts p JOIN post_reads r ON r.post_id=p.id;
SELECT /* CASE negative-fanout-nonkey-count */ COUNT(DISTINCT p.author_id) FROM posts p JOIN post_reads r ON r.post_id=p.id;
SELECT /* CASE negative-fanout-side-value */ COUNT(DISTINCT p.id),r.post_id FROM posts p JOIN post_reads r ON r.post_id=p.id GROUP BY r.post_id;
SELECT /* CASE negative-max-outer-owner */ q.id FROM posts q GROUP BY q.id HAVING EXISTS (SELECT p.parent_id FROM posts p GROUP BY p.parent_id HAVING NOT EXISTS(SELECT 1 FROM posts old WHERE old.parent_id=p.parent_id) OR MAX(q.created_at)<'2025-01-01');
SELECT /* CASE negative-max-outer-key */ q.id FROM posts q WHERE EXISTS (SELECT q.id FROM posts p GROUP BY q.id HAVING NOT EXISTS(SELECT 1 FROM posts old WHERE old.id=q.id) OR MAX(p.created_at)<'2025-01-01');
SELECT /* CASE negative-count-outer-owner */ q.slug FROM nullable_slugs q GROUP BY q.slug HAVING EXISTS (SELECT 1 FROM posts p WHERE COUNT(q.slug)>0);
